tool_input.command:
cat > guren.arch.ts <<'EOF'
import { defineArchRules } from '@guren/cli/arch'

export default defineArchRules({
  includeTypeImports: true,
  layers: {
    blog: ['app/**', 'routes/**'],
    newsletter: 'modules/newsletter/**',
  },
  rules: [
    {
      from: 'blog',
      disallow: 'newsletter',
      message: 'The newsletter module is self-contained; app/ and routes/ must not depend on it.',
    },
  ],
})
EOF
echo "import '../../modules/newsletter/index.ts'" > app/zz.ts; echo "import '../modules/newsletter/db/schema.ts'" > routes/zz.ts
bunx guren check --arch 2>&1 | grep -E "ERROR|fail|Results|Arch" ; rm app/zz.ts routes/zz.ts
bunx guren check 2>&1 | grep -E "ERROR|Results|Arch"; bun run typecheck | tail -2; bun test 2>&1 | grep -E "pass|fail"
